def find_modules():
    return [
        name for name, obj in globals().items() 
        if isinstance(obj, ModuleType) and ('agent' in name.lower() or 'rlm' in name.lower())
    ]

print("Module names containing 'agent' or 'rlm':")
for name in find_modules():
    print(f"  {name}")

